// Bitmap font for the UI (docs/UX.md section 12). The table is generated by
// tools/ux_mock/gen_font.py from the mockups' pgfont.py into font_data.cpp.
#pragma once
#include <cstdint>

namespace pg {
namespace ui {

constexpr int kFontFirst = 0x20;
constexpr int kFontCount = 95;     // 0x20..0x7E
constexpr int kIconCount = 17;     // codes 0x80..0x90

extern const uint8_t kFontS[kFontCount][5];
extern const uint8_t kFontIcons[kIconCount][5];

// Icon codes, usable inside string literals by concatenation: "P" ICON_PLAY "01".
#define PG_ICON_PLAY  "\x80"
#define PG_ICON_STOP  "\x81"
#define PG_ICON_REC   "\x82"
#define PG_ICON_RING  "\x83"
#define PG_ICON_UP    "\x84"
#define PG_ICON_DOWN  "\x85"
#define PG_ICON_LEFT  "\x86"
#define PG_ICON_RIGHT "\x87"
#define PG_ICON_LOCK  "\x88"
#define PG_ICON_SLIDE "\x89"
#define PG_ICON_NOTE  "\x8A"
#define PG_ICON_CHAIN "\x8B"
#define PG_ICON_CHECK "\x8C"
#define PG_ICON_DOT   "\x8D"
#define PG_ICON_BLOCK "\x8E"
#define PG_ICON_DUCK  "\x8F"
#define PG_ICON_TRI_R "\x90"

// 5 column bytes for a character (bit 0 = top row); unknown characters draw '?'.
inline const uint8_t* glyph(uint8_t c) {
  if (c >= 0x80 && c < 0x80 + kIconCount) return kFontIcons[c - 0x80];
  if (c < kFontFirst || c >= kFontFirst + kFontCount) c = '?';
  return kFontS[c - kFontFirst];
}

}  // namespace ui
}  // namespace pg
